<?php
require_once __DIR__.'/app/lib/Db.php';
$config=require __DIR__.'/app/config.php';
$pdo=Db::pdo();
$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function initials($name){$parts=preg_split('/\s+/',trim((string)$name));$out='';foreach(array_slice($parts,0,2) as $x){if($x!=='')$out.=strtoupper(substr($x,0,1));}return $out?:'TS';}
function valid_logo($path){if(!$path||!str_starts_with($path,'/media/software/')||str_contains($path,'..'))return null;$full=__DIR__.$path;return is_file($full)?$path:null;}
function label($v){return ucwords(str_replace('_',' ',(string)$v));}
function status_class($v){if($v==='supported')return 'ok';if($v==='not_supported')return 'no';if(in_array($v,['unknown','not_yet_verified'],true))return 'unknown';return 'partial';}
function pct($v){return (int)round(((float)$v)*100);}
if(!preg_match('#^/compare/([a-z0-9-]+)-vs-([a-z0-9-]+)/?$#',$path,$m)){http_response_code(404);exit('Not found');}
$requested=[$m[1],$m[2]];$canonical=$requested;sort($canonical,SORT_STRING);$canonicalSlug=implode('-vs-',$canonical);
if($canonicalSlug!==$m[1].'-vs-'.$m[2]){header('Location: '.rtrim($config['site_url'],'/').'/compare/'.$canonicalSlug,true,301);exit;}
$st=$pdo->prepare("SELECT p.id,p.name,p.slug,p.short_description,p.logo_path,p.last_reviewed_at,p.category_id,v.name vendor,c.name category,c.slug category_slug FROM products p LEFT JOIN vendors v ON v.id=p.vendor_id LEFT JOIN categories c ON c.id=p.category_id WHERE p.slug IN (?,?) AND p.status='active'");
$st->execute($canonical);$products=$st->fetchAll();if(count($products)!==2){http_response_code(404);exit('Not found');}
usort($products,fn($a,$b)=>array_search($a['slug'],$canonical,true)<=>array_search($b['slug'],$canonical,true));
$a=$products[0];$b=$products[1];$ids=[$a['id'],$b['id']];
$q=$pdo->prepare("SELECT pc.product_id,c.name,c.slug,mo.name module,pc.support_status,pc.confidence_score,pc.implementation_type,pc.limitations,pc.last_verified_at FROM product_capabilities pc JOIN capabilities c ON c.id=pc.capability_id JOIN modules mo ON mo.id=c.module_id WHERE pc.product_id IN (?,?) AND pc.edition_id IS NULL ORDER BY mo.name,c.name,pc.product_id");
$q->execute($ids);$facts=$q->fetchAll();$matrix=[];
foreach($facts as $f){$key=$f['slug'];if(!isset($matrix[$key]))$matrix[$key]=['name'=>$f['name'],'slug'=>$f['slug'],'module'=>$f['module'],'rows'=>[]];$matrix[$key]['rows'][$f['product_id']]=$f;}
$q=$pdo->prepare("SELECT pi.product_id,i.name,i.slug,pi.support_status,pi.confidence_score FROM product_integrations pi JOIN integrations i ON i.id=pi.integration_id WHERE pi.product_id IN (?,?) ORDER BY i.name,pi.product_id");$q->execute($ids);$intMatrix=[];foreach($q->fetchAll() as $r){$intMatrix[$r['slug']]['name']=$r['name'];$intMatrix[$r['slug']]['rows'][$r['product_id']]=$r;}
$q=$pdo->prepare("SELECT pd.product_id,d.name,d.slug,pd.support_status,pd.confidence_score FROM product_deployments pd JOIN deployment_models d ON d.id=pd.deployment_model_id WHERE pd.product_id IN (?,?) ORDER BY d.name,pd.product_id");$q->execute($ids);$depMatrix=[];foreach($q->fetchAll() as $r){$depMatrix[$r['slug']]['name']=$r['name'];$depMatrix[$r['slug']]['rows'][$r['product_id']]=$r;}
$summary=[];foreach($ids as $id)$summary[$id]=['supported'=>0,'partial'=>0,'unknown'=>0,'not_supported'=>0,'known_conf'=>[]];
foreach($facts as $f){$id=$f['product_id'];$s=$f['support_status'];if($s==='supported')$summary[$id]['supported']++;elseif($s==='not_supported')$summary[$id]['not_supported']++;elseif(in_array($s,['unknown','not_yet_verified'],true))$summary[$id]['unknown']++;else $summary[$id]['partial']++;if(!in_array($s,['unknown','not_yet_verified'],true))$summary[$id]['known_conf'][]=(float)$f['confidence_score'];}
foreach($ids as $id)$summary[$id]['avg_conf']=$summary[$id]['known_conf']?round(array_sum($summary[$id]['known_conf'])/count($summary[$id]['known_conf'])*100):0;
$canonicalUrl=rtrim($config['site_url'],'/').'/compare/'.$canonicalSlug;$desc='Evidence-backed comparison of '.$a['name'].' and '.$b['name'].' across capabilities, integrations, deployment options, confidence and known limitations.';
$ld=['@context'=>'https://schema.org','@type'=>'WebPage','name'=>$a['name'].' vs '.$b['name'],'url'=>$canonicalUrl,'description'=>$desc,'mainEntity'=>[['@type'=>'SoftwareApplication','name'=>$a['name'],'url'=>rtrim($config['site_url'],'/').'/software/'.$a['slug']],['@type'=>'SoftwareApplication','name'=>$b['name'],'url'=>rtrim($config['site_url'],'/').'/software/'.$b['slug']]]];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($a['name'])?> vs <?=e($b['name'])?> | TechSelectAI</title><meta name="description" content="<?=e($desc)?>"><link rel="canonical" href="<?=e($canonicalUrl)?>"><meta property="og:title" content="<?=e($a['name'])?> vs <?=e($b['name'])?> | TechSelectAI"><meta property="og:description" content="<?=e($desc)?>"><meta property="og:url" content="<?=e($canonicalUrl)?>"><script type="application/ld+json"><?=json_encode($ld,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?></script><style>:root{--navy:#123b67;--ink:#172033;--muted:#64748b;--line:#e2e8f0;--soft:#f7fafc;--green:#137a55;--greenbg:#e9f8f1;--amber:#95610a;--amberbg:#fff7df;--red:#b42318;--redbg:#fff0ee}*{box-sizing:border-box}body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink);background:#fff}a{color:#145ea8}header{display:flex;justify-content:space-between;align-items:center;padding:17px max(24px,5vw);border-bottom:1px solid var(--line)}header>a{font-size:20px;font-weight:800;color:var(--navy);text-decoration:none}nav a{margin-left:20px;text-decoration:none;font-weight:650;color:#334155}.wrap{max-width:1180px;margin:auto;padding:0 24px}.crumbs{font-size:13px;color:var(--muted);padding-top:25px}.hero{padding:34px 0 24px}.eyebrow{font-size:12px;letter-spacing:.09em;text-transform:uppercase;color:#52708b;font-weight:800}.hero h1{font-size:clamp(36px,5vw,58px);line-height:1.04;margin:8px 0 13px}.lead{font-size:18px;line-height:1.65;color:#536174;max-width:920px}.versus{display:grid;grid-template-columns:1fr auto 1fr;gap:18px;align-items:stretch}.product{border:1px solid var(--line);border-radius:17px;padding:20px}.mark{width:64px;height:64px;border-radius:15px;border:1px solid #dbe5ec;background:#f4f8fa;display:grid;place-items:center;overflow:hidden;color:var(--navy);font-weight:850}.mark img{width:100%;height:100%;object-fit:contain;padding:7px}.product h2{margin:12px 0 5px}.product p{color:var(--muted);line-height:1.5}.vs{align-self:center;font-weight:850;color:#789}.stats{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.pill{padding:6px 9px;border-radius:999px;background:#f1f6f9;font-size:12px;font-weight:700;color:#31516e}.section{padding-top:36px}.section h2{font-size:28px;margin:0 0 8px}.intro{color:var(--muted);margin:0 0 16px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:14px}table{width:100%;border-collapse:collapse;min-width:820px}th,td{text-align:left;padding:13px 14px;border-bottom:1px solid var(--line);vertical-align:top}th{background:var(--soft);font-size:12px;color:#526071}tr:last-child td{border-bottom:0}.badge{display:inline-block;border-radius:999px;padding:5px 9px;font-size:11px;font-weight:800}.badge.ok{color:var(--green);background:var(--greenbg)}.badge.partial{color:var(--amber);background:var(--amberbg)}.badge.no{color:var(--red);background:var(--redbg)}.badge.unknown{color:#596579;background:#eef2f7}.small{display:block;color:var(--muted);font-size:12px;line-height:1.45;margin-top:4px}.cta{margin:42px 0 0;padding:26px;border-radius:17px;background:linear-gradient(135deg,#f0f8fb,#f5f8fc);border:1px solid #d5e5ed}.btn{display:inline-block;margin-top:8px;padding:11px 16px;border-radius:10px;background:var(--navy);color:#fff;text-decoration:none;font-weight:750}footer{margin:56px 0 30px;color:var(--muted);font-size:13px}@media(max-width:720px){nav{display:none}.versus{grid-template-columns:1fr}.vs{text-align:center}}</style></head><body><header><a href="/">TechSelectAI</a><nav><a href="/software">Software</a><a href="/methodology">Methodology</a><a href="/">Get Advice</a></nav></header><main class="wrap"><div class="crumbs"><a href="/">Home</a> / Compare / <?=e($a['name'])?> vs <?=e($b['name'])?></div><section class="hero"><div class="eyebrow">Evidence-backed software comparison</div><h1><?=e($a['name'])?> vs <?=e($b['name'])?></h1><p class="lead"><?=e($desc)?></p></section><section class="versus"><?php foreach([$a,$b] as $x):$logo=valid_logo($x['logo_path']);$s=$summary[$x['id']];?><article class="product"><div class="mark"><?php if($logo):?><img src="<?=e($logo)?>" alt="<?=e($x['name'])?> logo"><?php else:?><?=e(initials($x['name']))?><?php endif;?></div><div class="eyebrow" style="margin-top:12px"><?=e($x['vendor']?:'Vendor not recorded')?> · <?=e($x['category']?:'Category not recorded')?></div><h2><a href="/software/<?=e($x['slug'])?>"><?=e($x['name'])?></a></h2><p><?=e($x['short_description']?:'Evidence-backed product profile.')?></p><div class="stats"><span class="pill"><?=$s['supported']?> supported</span><span class="pill"><?=$s['partial']?> conditional</span><span class="pill"><?=$s['unknown']?> unknown</span><span class="pill"><?=$s['not_supported']?> not supported</span><span class="pill"><?=$s['avg_conf']?>% known-fact confidence</span></div></article><?php if($x['id']===$a['id']):?><div class="vs">VS</div><?php endif;?><?php endforeach;?></section><section class="section"><h2>Capability comparison</h2><p class="intro">Status and confidence reflect recorded evidence. Unknown means not yet verified, not unsupported.</p><div class="table-wrap"><table><thead><tr><th>Capability</th><th><?=e($a['name'])?></th><th><?=e($b['name'])?></th></tr></thead><tbody><?php foreach($matrix as $x):$ra=$x['rows'][$a['id']]??null;$rb=$x['rows'][$b['id']]??null;?><tr><td><strong><a href="/capabilities/<?=e($x['slug'])?>"><?=e($x['name'])?></a></strong><span class="small"><?=e($x['module'])?></span></td><?php foreach([$ra,$rb] as $r):?><td><?php if(!$r):?><span class="badge unknown">Not recorded</span><?php else:?><span class="badge <?=e(status_class($r['support_status']))?>"><?=e(label($r['support_status']))?></span><span class="small"><?=pct($r['confidence_score'])?>% confidence<?=!empty($r['implementation_type'])?' · '.e($r['implementation_type']):''?></span><?php if(!empty($r['limitations'])):?><span class="small"><?=e($r['limitations'])?></span><?php endif;?><?php endif;?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section><?php if($intMatrix):?><section class="section"><h2>Integration comparison</h2><div class="table-wrap"><table><thead><tr><th>Integration</th><th><?=e($a['name'])?></th><th><?=e($b['name'])?></th></tr></thead><tbody><?php foreach($intMatrix as $x):?><tr><td><a href="/integrations/<?=e(array_search($x,$intMatrix,true)?:'')?>"><?=e($x['name'])?></a></td><?php foreach($ids as $id):$r=$x['rows'][$id]??null;?><td><?php if($r):?><span class="badge <?=e(status_class($r['support_status']))?>"><?=e(label($r['support_status']))?></span><span class="small"><?=pct($r['confidence_score'])?>% confidence</span><?php else:?><span class="badge unknown">Not recorded</span><?php endif;?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section><?php endif;?><?php if($depMatrix):?><section class="section"><h2>Deployment comparison</h2><div class="table-wrap"><table><thead><tr><th>Deployment model</th><th><?=e($a['name'])?></th><th><?=e($b['name'])?></th></tr></thead><tbody><?php foreach($depMatrix as $x):?><tr><td><?=e($x['name'])?></td><?php foreach($ids as $id):$r=$x['rows'][$id]??null;?><td><?php if($r):?><span class="badge <?=e(status_class($r['support_status']))?>"><?=e(label($r['support_status']))?></span><span class="small"><?=pct($r['confidence_score'])?>% confidence</span><?php else:?><span class="badge unknown">Not recorded</span><?php endif;?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section><?php endif;?><section class="cta"><div class="eyebrow">Independent software advice</div><h2>Which product fits your company better?</h2><p>A feature comparison is not the same as a recommendation. TechSelectAI can evaluate both products against your must-have capabilities, integrations, deployment constraints, security requirements, region and budget.</p><a class="btn" href="/?considering=<?=rawurlencode($a['name'].' vs '.$b['name'])?>">Evaluate for my company</a></section><footer>TechSelectAI uses evidence-backed product data. Unknown means not yet verified; it does not mean unsupported. Vendor names and trademarks belong to their respective owners.</footer></main></body></html>